#!/usr/bin/env python3
"""Generate src/accel/p256_curve.inc: NIST P-256 (secp256r1) constants and the
fixed-base wNAF table for G, as eight 32-bit limbs per value, limb 0 holding
bits 0..31 (the representation src/accel/p256_verify.c works with).

k_p256_g_odd[i] = (2i+1) * G affine, 16 entries for wNAF window w = 6
(digits in +-{1,3,...,31}); computed here with exact integer arithmetic.

Usage: python tools/gen_p256.py --out src/accel/p256_curve.inc
       (without --out the same text goes to stdout)

With --wrap-vector it instead prints a C test vector (public key, hash, r, s)
whose verification requires the wrap-around comparison x_R == r + n: the
signature is constructed so that R = u1*G + u2*Q is a curve point T with
x_T in [n, p) and r = x_T - n, which no r-only comparison can accept.
"""
import hashlib
import sys

P = 0xffffffff00000001000000000000000000000000ffffffffffffffffffffffff
N = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551
# b is pinned by check_group(): it must be the value that puts G on the curve.
B = 0x5ac635d8aa3a93e7b3ebbd55769886bc651d06b0cc53b0f63bce3c3e27d2604b
GX = 0x6b17d1f2e12c4247f8bce6e563a440f277037d812deb33a0f4a13945d898c296
GY = 0x4fe342e2fe1a7f9b8ee7eb4a7c0f9e162bce33576b315ececbb6406837bf51f5


def inv(a, m):
    return pow(a, -1, m)


def assert_on_curve(x, y):
    assert 0 <= x < P and 0 <= y < P
    assert (y * y - (x * x * x - 3 * x + B)) % P == 0


def ec_add(p1, p2):
    """Affine addition, exact integers; p1 or p2 may be None (infinity)."""
    if p1 is None:
        return p2
    if p2 is None:
        return p1
    x1, y1 = p1
    x2, y2 = p2
    if x1 == x2:
        if (y1 + y2) % P == 0:
            return None
        lam = (3 * x1 * x1 - 3) * inv(2 * y1, P) % P
    else:
        lam = (y2 - y1) * inv((x2 - x1) % P, P) % P
    x3 = (lam * lam - x1 - x2) % P
    return x3, (lam * (x1 - x3) - y1) % P


def ec_mul(k, p1):
    r = None
    while k:
        if k & 1:
            r = ec_add(r, p1)
        p1 = ec_add(p1, p1)
        k >>= 1
    return r


def limbs(v):
    out = []
    for _ in range(8):
        out.append(v & 0xFFFFFFFF)
        v >>= 32
    assert v == 0
    return out


def limbs_c(v):
    return "{" + ", ".join("0x%08xu" % l for l in limbs(v)) + "}"


def check_group():
    assert_on_curve(GX, GY)
    # b is exactly the value that puts G on the curve (and G is the standard
    # generator), so a mistyped constant cannot pass both checks.
    assert (GY * GY - (GX * GX * GX - 3 * GX + B)) % P == 0
    assert ec_mul(N, (GX, GY)) is None, "N*G must be the point at infinity"
    assert N < P and (P - N) % N != 0


def emit_curve():
    check_group()
    print("/* Generated by tools/gen_p256.py; do not edit.")
    print(" * NIST P-256 (secp256r1) constants as eight little-endian limbs:")
    print(" * limb 0 holds bits 0..31 of each value. */")
    print("static const uint32_t k_p256_p[8] = " + limbs_c(P) + ";")
    print("static const uint32_t k_p256_n[8] = " + limbs_c(N) + ";")
    print("static const uint32_t k_p256_b[8] = " + limbs_c(B) + ";")
    print()
    print("/* k_p256_g_odd[i] = (2i+1) * G, affine: wNAF window w = 6 digits")
    print(" * (|d| in {1,3,...,31}, index (|d|-1)/2). */")
    print("static const uint32_t k_p256_g_odd[16][2][8] = {")
    g = (GX, GY)
    m2 = ec_add(g, g)  # 2G
    pt = g
    for i in range(16):
        assert pt is not None and i * 2 + 1 < N
        assert_on_curve(*pt)
        print("    { " + limbs_c(pt[0]) + ", " + limbs_c(pt[1]) + " }," +
              (" /* %dG */" % (2 * i + 1)))
        pt = ec_add(pt, m2)  # (2i+3)G
    print("};")


def wrap_vector():
    """A signature whose verification needs the x_R == r + n comparison."""
    check_group()
    # Any on-curve point T with x_T in [n, p): walk down from p - 1.
    t = None
    x = P - 1
    while t is None:
        rhs = (x * x * x - 3 * x + B) % P
        y = pow(rhs, (P + 1) // 4, P)  # p = 3 mod 4
        if y * y % P == rhs and y != 0:
            t = (x, y)
        else:
            x -= 1
    assert t[0] >= N, "x_T must allow r = x_T - n >= 0"
    r = t[0] - N
    assert 1 <= r < N and r + N < P
    # Fixed hash (SHA-256 of "p256-wrap") and s; then Q makes
    # u1*G + u2*Q = T for u1 = e/s, u2 = r/s.
    h1 = int.from_bytes(hashlib.sha256(b"p256-wrap").digest(), "big")
    s = 0x5353aa3bb1bba1ccddaaddeeff0f0f0fabcdefabcdefabcdefabcdef0f0f12 % N
    assert 1 <= s < N
    w = inv(s, N)
    u1 = h1 * w % N
    u2 = r * w % N
    # Q = u2^-1 * (T - u1*G) = u2^-1 * (T + (N - u1)*G)
    p_prime = ec_add(t, ec_mul((N - u1) % N, (GX, GY)))
    d = inv(u2, N)
    q = ec_mul(d, p_prime)
    assert q is not None and q[0] not in (0,) and q != (GX, GY)
    assert_on_curve(*q)
    # End-to-end check: the verify equation must reproduce T exactly.
    rr = ec_add(ec_mul(u1, (GX, GY)), ec_mul(u2, q))
    assert rr == t, "constructed signature does not verify"
    assert (rr[0] % N) == r and rr[0] >= N

    def cbytes(bs):
        return ", ".join("0x%02x" % b for b in bs)

    hash_bytes = hashlib.sha256(b"p256-wrap").digest()
    pub = b"\x04" + q[0].to_bytes(32, "big") + q[1].to_bytes(32, "big")
    print("/* Wrap-around vector: x_R = r + n (r + n < p). Generated by")
    print(" * tools/gen_p256.py --wrap-vector; the first comparison")
    print(" * (X == r*Z^2) fails, only X == (r+n)*Z^2 accepts. */")
    print("static const uint8_t k_p256_wrap_pub[65] = {")
    print("    " + cbytes(pub[:33]) + ",")
    print("    " + cbytes(pub[33:]) + "};")
    print("static const uint8_t k_p256_wrap_hash[32] = {")
    print("    " + cbytes(hash_bytes) + "};")
    print("static const uint8_t k_p256_wrap_sig[64] = {")
    print("    " + cbytes(r.to_bytes(32, "big")) + ",")
    print("    " + cbytes(s.to_bytes(32, "big")) + "};")


def identity_vector():
    """A signature whose verification computes R = u1*G + u2*Q = O: with
    Q = dG, choosing the hash value e = -r*d (mod n) gives u1 + u2*d == 0.
    R = O must be rejected with INVALID_SIGNATURE."""
    check_group()
    d = 0x1a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d5e6f708192a3b4c5d6e7f80 % N
    assert 1 <= d < N
    q = ec_mul(d, (GX, GY))
    assert_on_curve(*q)
    r = 0xC0FFEE1234567890ABCDEF0123456789DEADBEEFCAFEBABE0123456789ABCDE % N
    assert 1 <= r < N
    e = (-r * d) % N
    s = 0x5353AA3BB1BBA1CCDDAADDEEFF0F0F0FABCDEFABCDEFABCDEFABCDEF0F0F12 % N
    assert 1 <= s < N
    w = inv(s, N)
    u1 = e * w % N
    u2 = r * w % N
    assert (u1 + u2 * d) % N == 0
    assert ec_add(ec_mul(u1, (GX, GY)), ec_mul(u2, q)) is None, "R must be O"

    def cbytes(bs):
        return ", ".join("0x%02x" % b for b in bs)

    pub = b"\x04" + q[0].to_bytes(32, "big") + q[1].to_bytes(32, "big")
    print("/* Identity vector: e = -r*d (mod n), so R = u1*G + u2*Q = O;")
    print(" * generated by tools/gen_p256.py --identity-vector. */")
    print("static const uint8_t k_p256_ident_pub[65] = {")
    print("    " + cbytes(pub[:33]) + ",")
    print("    " + cbytes(pub[33:]) + "};")
    print("static const uint8_t k_p256_ident_hash[32] = {")
    print("    " + cbytes(e.to_bytes(32, "big")) + "};")
    print("static const uint8_t k_p256_ident_sig[64] = {")
    print("    " + cbytes(r.to_bytes(32, "big")) + ",")
    print("    " + cbytes(s.to_bytes(32, "big")) + "};")


if __name__ == "__main__":
    argv = sys.argv[1:]
    out = None
    if "--out" in argv:
        i = argv.index("--out")
        out = argv[i + 1]
        del argv[i:i + 2]
    if argv == ["--wrap-vector"]:
        wrap_vector()
    elif argv == ["--identity-vector"]:
        identity_vector()
    elif argv == []:
        if out is None:
            emit_curve()
        else:
            import io

            buf = io.StringIO()
            sys.stdout = buf
            emit_curve()
            sys.stdout = sys.__stdout__
            with open(out, "w", encoding="ascii", newline="\n") as f:
                f.write(buf.getvalue())
    else:
        sys.exit("usage: gen_p256.py [--out FILE] | --wrap-vector | --identity-vector")
